for yy in range(0,250,5):
 m=y[yy]<50
 runs=[]; st=None
 for x,v in enumerate(m):
  if v and st is None:st=x
  if st is not None and (not v or x==511):
   en=x if v and x==511 else x-1
   if en-st>=2:runs.append((st,en,round(float(y[yy,st:en+1].mean()))))
   st=None
 if runs: print(yy,runs)
